INSERT INTO user_login_history (
	USER_NO
	, IP_ADDRESS
	, ACCESS_INFO
	, OS_NAME
	, APP_NAME
	, APP_VERSION
	, LOGIN_DATE
) VALUES (
	#{userNo}
	, #{ipAddress}
	, #{accessInfo}
	, #{osName}
	, #{appName}
	, #{appVersion}
	, NOW()
)

INSERT INTO admin_login_history (
	ADMIN_NO
	, IP_ADDRESS
	, ACCESS_INFO
	, OS_NAME
	, APP_NAME
	, APP_VERSION
	, LOGIN_DATE
) VALUES (
	#{adminNo}
	, #{ipAddress}
	, #{accessInfo}
	, #{osName}
	, #{appName}
	, #{appVersion}
	, NOW()
)
